// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzzed params: the target callee selector choice and an arbitrary bool to demonstrate fuzzing
    function testFuzz_property(address calleeAddr, bytes1 selectorByte) public {
        // Domain: ensure calleeAddr is not zero to be a valid contract address after deployment
        vm.assume(calleeAddr != address(0));

        // Deploy a recorder/reverter pair at deterministic addresses by using CREATE with salt via new
        // We need a callee that we control; deploy a Reverter that always reverts on fallback
        Reverter reverter = new Reverter();
        Recorder recorder = new Recorder();

        // Choose which helper to call based on the fuzzed selectorByte low bit
        address target = (uint8(selectorByte) & 1 == 1) ? address(reverter) : address(recorder);

        // Prepare calldata: any data is fine; use a non-empty calldata to ensure forwarded data exists
        bytes memory data = abi.encodeWithSelector(bytes4(0xd22b59df), uint256(1)); // arbitrary selector+arg

        // Call forward and record whether it reverted (ok == true) or not
        bool ok;
        try c.forward(target, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (reference C): ok equals the success of the low-level call to callee.
        // For our recorder, the low-level call will succeed (so ok must be true).
        // For our reverter, the low-level call will revert (so ok must be false).
        // We assert that behavior for both helper types based on which we selected.

        if (target == address(recorder)) {
            // recorder's fallback accepts the call and records it -> call succeeds
            assertTrue(ok);
            // additionally check recorder recorded the calldata and caller
            assertTrue(recorder.callCount() == 1);
            (address from, bytes memory got) = recorder.lastCall();
            assertTrue(from == address(c));
            assertTrue(got.length == data.length);
        } else {
            // reverter's fallback always reverts -> call fails
            assertTrue(!ok);
        }
    }
}

// Helper that always reverts on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

// Helper that records incoming calls (caller and calldata) and accepts them
contract Recorder {
    uint256 public callCnt;
    address public lastFrom;
    bytes public lastData;

    fallback() external payable {
        callCnt += 1;
        lastFrom = msg.sender;
        lastData = msg.data;
    }
    receive() external payable {
        callCnt += 1;
        lastFrom = msg.sender;
        lastData = "";
    }

    function callCount() external view returns (uint256) { return callCnt; }
    function lastCall() external view returns (address, bytes memory) { return (lastFrom, lastData); }
}
